suppressPackageStartupMessages({library(data.table);library(readxl)})
out<-'audit/20261011_all_groups_algorithm_audit/kla_tissues';rawroot<-'/Users/gzy2520/Desktop/Research/kla/data'
# Reuse only identifier and detection helpers, not prebuilt membership.
code<-readLines(file.path(out,'audit.R'));eval(parse(text=code[5:8]))
pos<-function(x){x<-suppressWarnings(as.numeric(x));is.finite(x)&x>0};flag<-function(x)tolower(trimws(as.character(x)))%in%c('+','1','true','yes','y')
g<-fread('data/publication_input/human_ddr_go_annotations.tsv');ddr<-parse_new(g[(is.na(`TAXON ID`)|`TAXON ID`==9606)&`GENE PRODUCT DB`=='UniProtKB'&!grepl('(^|\\|)NOT($|\\|)',QUALIFIER),`GENE PRODUCT ID`])
hp<-file.path(rawroot,'PXD050470/supplementary/prca2331-sup-0005-tables3.xlsx');h<-as.data.table(read_excel(hp,skip=12));cols<-grep('Intensity_',names(h),value=TRUE)
hstats<-rbindlist(lapply(cols,function(c){z<-h[[c]];data.table(Column=c,Rows=length(z),NAcount=sum(is.na(z)),Zero=sum(z==0,na.rm=TRUE),Positive=sum(pos(z)),Minimum=min(z,na.rm=TRUE),NAtMinimum=sum(z==min(z,na.rm=TRUE),na.rm=TRUE),Distinct=uniqueN(z))}));fwrite(hstats,file.path(out,'hippocampus_intensity_diagnostics.csv'))
h12<-as.data.table(read_excel(sub('0005-tables3','0014-tables12',hp),skip=10));a3<-parse_new(h[['Proteins accession']]);a12<-parse_new(h12[['Proteins accession']]);fwrite(data.table(S3N=length(a3),S12N=length(a12),S12Only=length(setdiff(a12,a3)),S3Only=length(setdiff(a3,a12))),file.path(out,'hippocampus_s3_s12_compare.csv'))
fwrite(data.table(Row=1:nrow(h),Accession=h[['Proteins accession']],H072=h[['Intensity_H072']],H081=h[['Intensity_H081']],H187=h[['Intensity_H187']]),file.path(out,'hippocampus_source_intensities.csv'))
tp<-file.path(rawroot,'PXD033146/search_results/extracted_pairing/search_result-HA119TPLa/La (K)Sites.txt');t<-fread(tp,quote='',integer64='double');bk<-!flag(t$Reverse)&!flag(t[['Potential contaminant']])&!is.na(t$id)&pos(t[['Localization prob']]);sets<-list(AllLocalized=parse_new(t$Proteins[bk]));rows<-list();cp<-list()
for(i in 1:6){cs<-paste0('Reporter intensity corrected ',i,'___',1:3);det<-Reduce(`|`,lapply(cs,function(c)pos(t[[c]])));sets[[paste0('Channel',i)]]<-parse_new(t$Proteins[bk&det]);rows[[i]]<-data.table(Channel=i,LocalizedSites=sum(bk),PositiveSites=sum(bk&det),PositiveReporter1=sum(bk&pos(t[[cs[1]]])),PositiveReporter2=sum(bk&pos(t[[cs[2]]])),PositiveReporter3=sum(bk&pos(t[[cs[3]]])),AllZeroSites=sum(bk&!det));cp[[i]]<-det}
sets[['RCT123Union']]<-sort(unique(unlist(sets[paste0('Channel',1:3)])));sets[['All6Union']]<-sort(unique(unlist(sets[paste0('Channel',1:6)])))
fwrite(rbindlist(lapply(names(sets),function(n)data.table(Scope=n,N=length(sets[[n]]),DDR=sum(sets[[n]]%in%ddr),Percent=100*mean(sets[[n]]%in%ddr)))),file.path(out,'tendon_channel_scope.csv'));fwrite(rbindlist(rows),file.path(out,'tendon_channel_detection.csv'))
removed<-setdiff(sets$AllLocalized,sets$RCT123Union);a<-data.table(BaseAccession=removed,IsDdr=removed%in%ddr,OtherChannels456=removed%in%unique(unlist(sets[paste0('Channel',4:6)])));fwrite(a,file.path(out,'tendon_legacy_union_removed.csv'))
# Record source site rows whose accession text has contamination fragments or colon syntax.
allpaths<-unique(fread(file.path(out,'source_evidence.csv'))[,.(SourceFile,AccessionField)]);audit<-list();for(i in seq_len(nrow(allpaths))){r<-allpaths[i];if(grepl('xlsx$',r$SourceFile))next;z<-fread(r$SourceFile,quote='"',integer64='double',check.names=FALSE);v<-z[[r$AccessionField]];ix<-which(grepl('CON__|REV__|:',v));if(length(ix))audit[[i]]<-data.table(SourceFile=r$SourceFile,Row=ix+1L,RawAccession=v[ix],Parsed=vapply(v[ix],function(a)paste(parse_new(a),collapse=';'),character(1)),Reverse=if('Reverse'%in%names(z))z$Reverse[ix]else'',Contaminant=if('Potential contaminant'%in%names(z))z[['Potential contaminant']][ix]else'')};fwrite(rbindlist(audit),file.path(out,'special_id_source_rows.csv'))
print(hstats);print(fread(file.path(out,'tendon_channel_scope.csv')))
